H=Path(__file__).resolve().parent;D=H/'native_live_point_memory_shadow_run_v1';rows=json.loads((D/'memory_shadow_rows.json').read_text());v=json.loads((H/'live_memory_occlusion_persistence_v1/visibility_rows.json').read_text());ph=np.load(D/'physics.npz');m=json.loads((D/'tentative_memory_snapshots/frame_140.json').read_text());points=np.concatenate([np.asarray(r['world']).reshape(-1,3) for r in m['records']]);t=[r['time_s'] for r in rows];fig,ax=plt.subplots(2,2,figsize=(10,7));ax[0,0].plot(ph['root_position_world_m'][:,0],ph['root_position_world_m'][:,1]);ax[0,0].scatter(*ph['root_position_world_m'][0,:2],label='Start');ax[0,0].set(title='Actual 14 s robot motion (offline truth)',xlabel='World X (m)',ylabel='World Y (m)',aspect='equal');ax[0,0].legend();ax[0,1].plot(t,[r['current_count'] for r in rows],label='Current');ax[0,1].plot(t,[r['historical_count'] for r in rows],label='Historical');ax[0,1].set(title='Correlated point records',xlabel='Simulation time (s)',ylabel='Records');ax[0,1].legend();ax[1,0].scatter(points[:,0],points[:,1],s=8,alpha=.25);ax[1,0].set(title='449 records; only 3 diagnostic XY bins',xlabel='Estimated world X (m)',ylabel='Estimated world Y (m)',aspect='equal');ax[1,1].plot(t,[r['hidden_at_least_one_eye'] for r in v],label='Hidden in one/both eyes');ax[1,1].plot(t,[r['historical_records'] for r in v],label='All historical records');ax[1,1].set(title='This sequence did not exercise occluded memory',xlabel='Simulation time (s)',ylabel='Record count');ax[1,1].legend();fig.suptitle('ONLINE read-only memory interface passed ONLY; source/navigation remain rejected',fontsize=10);fig.tight_layout();fig.savefig(H/'live_tentative_memory_actual_v1.png',dpi=160)
